SELECT mr.id, mr.patient_id, p.name AS patient_name, mr.doctor_id, u.name AS doctor_name,
       mr.record_date, mr.chief_complaint, mr.present_illness, mr.physical_examination,
       mr.diagnosis, mr.treatment_plan, mr.medication, mr.remarks
FROM medical_record mr
LEFT JOIN patient p ON mr.patient_id = p.id
LEFT JOIN doctor d ON mr.doctor_id = d.id
LEFT JOIN user u ON d.user_id = u.id


        AND mr.patient_id = #{patientId}


        AND mr.doctor_id = #{doctorId}


        AND mr.record_date >= #{startDate}


        AND mr.record_date <= #{endDate}


ORDER BY mr.record_date DESC, mr.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM medical_record mr


        AND mr.patient_id = #{patientId}


        AND mr.doctor_id = #{doctorId}


        AND mr.record_date >= #{startDate}


        AND mr.record_date <= #{endDate}

