patient_id = #{patientId}, doctor_id = #{doctorId}, record_date = #{recordDate}, chief_complaint = #{chiefComplaint}, present_illness = #{presentIllness}, physical_examination = #{physicalExamination}, diagnosis = #{diagnosis}, treatment_plan = #{treatmentPlan}, medication = #{medication}, remarks = #{remarks},
